namespace FitnessSimulator.Game.Tests.ConfigurationAcceptance
{
 // Disk files, production parser, production session. No root editing or injected catalog.
 public sealed class ConfigurationP1PublicRouteTests
 {
  private string output,sourceManifest;private Stopwatch clock;
  private static string Sha(string file){using(var h=SHA256.Create())using(var f=File.OpenRead(file))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  private static string Production=>Path.Combine(UnityEngine.Application.dataPath,"FitnessSimulator/Production");
  private static string Manifest(string root,string pattern)=>string.Join("\n",Directory.GetFiles(root,pattern,SearchOption.AllDirectories).OrderBy(x=>x,StringComparer.Ordinal).Select(f=>f.Substring(root.Length).Replace('\\','/')+" "+Sha(f)));
  [SetUp]public void Setup(){output=Path.Combine(Path.GetTempPath(),"Fitness-Configuration-P1",TestContext.CurrentContext.Test.Name+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(output);clock=Stopwatch.StartNew();sourceManifest=Manifest(Production,"*.cs");File.WriteAllText(Path.Combine(output,"source-manifest.txt"),sourceManifest);File.WriteAllText(Path.Combine(output,"assembly-hash.txt"),Sha(typeof(GameSession).Assembly.Location));}
  [TearDown]public void Finish(){Assert.That(Manifest(Production,"*.cs"),Is.EqualTo(sourceManifest),"Business source drift");File.WriteAllText(Path.Combine(output,"result.txt"),"status="+TestContext.CurrentContext.Result.Outcome+"\nseconds="+clock.Elapsed.TotalSeconds+"\nmaxSeconds=180\nmaxDays=2\nseed=1\n");TestContext.WriteLine(output);}
  internal string CopyBundle(string name,string from=null){string target=Path.Combine(output,name);Directory.CreateDirectory(target);from=from??Path.Combine(Production,"Resources/GameContent");foreach(string file in Directory.GetFiles(from,"*",SearchOption.AllDirectories)){string dest=Path.Combine(target,file.Substring(from.Length).TrimStart(Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest);}return target;}
  internal static T Doc<T>(string dir,string id) where T:class=>ContentJson.Deserialize<T>(id,File.ReadAllText(Path.Combine(dir,id+".json")));
  internal static void Save<T>(string dir,string id,T value) where T:class=>File.WriteAllText(Path.Combine(dir,id+".json"),ContentJson.Serialize(value));
  internal ContentPackage Load(string dir){var p=ContentPackage.FromDirectory(dir);GameSession.ValidateContentPackage(p);Assert.That(p.Source,Is.EqualTo("directory:"+Path.GetFullPath(dir)));File.WriteAllText(Path.Combine(dir,"loaded-evidence.txt"),"source="+p.Source+"\nraw="+p.RawHash+"\nresolved="+p.Hash+"\nversion="+p.Version+"\n"+Manifest(dir,"*.json"));return p;}
  private static void Different(ContentPackage a,ContentPackage b){Assert.That(b.Hash,Is.Not.EqualTo(a.Hash));Assert.That(b.RawHash,Is.Not.EqualTo(a.RawHash));}
  internal sealed class Run:IDisposable
  {
   public GameSession Session;public readonly string Dir,SavePath;private readonly ConfigurationP1PublicRouteTests owner;private readonly StreamWriter trace;private int operations,steps;public readonly HashSet<string> CompletedTitles=new HashSet<string>();
   public Run(ConfigurationP1PublicRouteTests owner,string name,ContentPackage p){this.owner=owner;Dir=Path.Combine(owner.output,name);Directory.CreateDirectory(Dir);SavePath=Path.Combine(Dir,"save");Session=GameSession.OpenAutomationContent(SavePath,1,p);trace=new StreamWriter(Path.Combine(Dir,"trace.jsonl"));Identity(p);}
   public T Read<T>(string id)=>JsonUtility.FromJson<T>(Session.InspectSnapshot().FindFragment(id,"player").Json);
   public void Identity(ContentPackage p){Assert.That(Session.LoadedContentHash,Is.EqualTo(p.Hash));Assert.That(Session.LoadedContentRawHash,Is.EqualTo(p.RawHash));Assert.That(Session.LoadedContentVersion,Is.EqualTo(p.Version));Assert.That(Session.LoadedContentSource,Is.EqualTo(p.Source));Assert.That(JsonUtility.ToJson(Session.InspectContent()),Is.EqualTo(JsonUtility.ToJson(p.Export())));}
   public void Bound(){Assert.That(owner.clock.Elapsed.TotalSeconds,Is.LessThan(180));Assert.That(++steps,Is.LessThan(20000));}
   public void Send(FrontendOption o,bool retry=false){Bound();Assert.That(++operations,Is.LessThan(2000));var v=Session.ReadView();var a=new FrontendAction{OperationId="configuration-p1/"+operations,RunId=v.RunId,ExpectedRevision=v.Revision,ActionId=o.Id,StringValue=o.StringValue,IntValue=o.IntValue};trace.WriteLine(JsonUtility.ToJson(v));trace.WriteLine(JsonUtility.ToJson(a));var r=Session.Execute(a);trace.WriteLine(JsonUtility.ToJson(r));Assert.That(r.Accepted,Is.True,r.Message);if(o.Id=="continue")CompletedTitles.Add(v.Title);if(retry){string before=JsonUtility.ToJson(Session.InspectSnapshot());Assert.That(Session.Execute(a).Accepted,Is.True);Assert.That(JsonUtility.ToJson(Session.InspectSnapshot()),Is.EqualTo(before));}}
   public void NewGame(){Send(Session.ReadView().Actions.First(x=>x.Enabled&&x.Id=="new-game"));Send(Session.ReadView().Actions.First(x=>x.Enabled&&x.Id=="save-plan"),true);Assert.That(Session.InspectSnapshot().FindFragment("content-package","shared"),Is.Not.Null);}
   public void Reopen(ContentPackage installed,ContentPackage expected,bool sameRoot=true){string before=JsonUtility.ToJson(Session.InspectSnapshot());Session.Dispose();Session=GameSession.OpenAutomationContent(SavePath,1,installed);Identity(expected);if(sameRoot)Assert.That(JsonUtility.ToJson(Session.InspectSnapshot()),Is.EqualTo(before));Send(Session.ReadView().Actions.First(x=>x.Enabled&&x.Id=="continue-game"));}
   public void Until(Func<FrontendView,bool> done){while(true){Bound();var v=Session.ReadView();Assert.That(v.ScreenId,Is.Not.EqualTo("error"),v.Body);Assert.That(Read<SessionState>("session").Day,Is.LessThanOrEqualTo(2));if(done(v))return;var a=v.Actions.Where(x=>x.Enabled).ToArray();FrontendOption next=a.FirstOrDefault(x=>x.Id=="meal"&&x.StringValue=="skip")??a.FirstOrDefault(x=>x.Id=="choose-entry"&&x.StringValue=="training-choice");foreach(string id in new[]{"story-continue","continue","shop-leave","item-use"})if(next==null)next=a.FirstOrDefault(x=>x.Id==id&&(id!="item-use"||x.StringValue.Contains("\"Skip\":true")));if(next!=null)Send(next);else{Assert.That(a.Any(x=>new[]{"begin-set","choose-entry","story-choice","next-day"}.Contains(x.Id)),Is.False,"Unplanned public decision; stop without hidden-state policy");trace.WriteLine("advance-ms=0");Session.Advance(0);}}}
   public void Dispose(){File.WriteAllText(Path.Combine(Dir,"final.json"),JsonUtility.ToJson(Session.InspectSnapshot(),true));File.WriteAllText(Path.Combine(Dir,"content.json"),JsonUtility.ToJson(Session.InspectContent(),true));File.WriteAllText(Path.Combine(Dir,"counters.txt"),"commands="+operations+"\nsteps="+steps);trace.Dispose();Session.Dispose();}
  }
  private static void AssertInitial(Run r,ContentPackage p){var d=p.Get<TemplatesDocument>("templates");var i=d.Initializations.Single(x=>x.Id==d.Templates.Single(t=>t.Id==d.DefaultId).InitializationId);var b=r.Read<BodyState>("body");Assert.That(b.Regions.Length,Is.EqualTo(21));Assert.That(b.Exercises.Length,Is.EqualTo(8));foreach(var expected in i.Body.Regions){var actual=b.Regions.Single(x=>x.RegionId==expected.RegionId);Assert.That(actual.StrengthMicro,Is.EqualTo(expected.StrengthMicro.Value));Assert.That(actual.LocalFatigueMicro,Is.EqualTo(expected.LocalFatigueMicro.Value));Assert.That(actual.TemporaryFatigueMicro,Is.EqualTo(expected.TemporaryFatigueMicro.Value));Assert.That(actual.InjuredDay,Is.EqualTo(expected.InjuredDay.Value));Assert.That(actual.ExpiresAtStartOfDay,Is.EqualTo(expected.ExpiresAtStartOfDay.Value));}foreach(var e in i.Body.Exercises){var a=b.Exercises.Single(x=>x.ExerciseId==e.ExerciseId);Assert.That(a.KnowledgeMicro,Is.EqualTo(e.KnowledgeMicro.Value));Assert.That(a.ProficiencyMicro,Is.EqualTo(e.ProficiencyMicro.Value));}Assert.That(b.StressMicro,Is.EqualTo(i.Body.StressMicro.Value));Assert.That(b.MentalStressMicro,Is.EqualTo(i.Body.MentalStressMicro.Value));Assert.That(b.BodyFatMicro,Is.EqualTo(i.Body.BodyFatMicro.Value));Assert.That(b.BaseCharmMicro,Is.EqualTo(i.Body.BaseCharmMicro.Value));var life=r.Read<LifeActorState>("life");Assert.That(life.Wallet.Balance,Is.EqualTo(i.Balance.Value));Assert.That(life.Wallet.Affluence,Is.EqualTo(i.Affluence.Value));foreach(var e in i.Training.Exercises){var a=r.Read<TrainingDayState>("training").Progress.Exercises.Single(x=>x.ExerciseId==e.ExerciseId);Assert.That(a.HighestUnlockedTier,Is.EqualTo(e.HighestUnlockedTier.Value));Assert.That(a.AutomaticTiers,Is.EqualTo(e.AutomaticTiers));}var inventory=p.Get<EconomyContentDocument>("economy").InitialInventory;Assert.That(i.InventoryInitialRef,Is.EqualTo(inventory.Id));var items=r.Read<InventoryState>("inventory").Items;Assert.That(items.Length,Is.EqualTo(inventory.Items.Length));Assert.That(items.Select(x=>x.ItemId).Distinct().Count(),Is.EqualTo(items.Length));foreach(var expected in inventory.Items){var actual=items.Single(x=>x.ItemId==expected.ItemId);Assert.That(actual.Quantity,Is.EqualTo(expected.Quantity));}var expectedRel=p.Get<RelationshipContentDocument>("relationships").InitialState;Assert.That(i.RelationshipInitialRef,Is.EqualTo(expectedRel.Id));var rel=r.Read<RelationshipState>("relationships");Assert.That(rel.CurrentBuddy,Is.EqualTo(expectedRel.CurrentBuddy));Assert.That(rel.PendingBuddy,Is.EqualTo(expectedRel.PendingBuddy));Assert.That(rel.PendingBuddyDay,Is.EqualTo(expectedRel.PendingBuddyDay));Assert.That(rel.PendingConfessionId,Is.EqualTo(expectedRel.PendingConfessionId));Assert.That(rel.NextConfessionDay,Is.EqualTo(expectedRel.NextConfessionDay));Assert.That(rel.RomanceEstablished,Is.EqualTo(expectedRel.RomanceEstablished));foreach(var e in expectedRel.Affections){var a=rel.Affections.Single(x=>x.CharacterId==e.CharacterId);Assert.That(a.Value,Is.EqualTo(e.Value));Assert.That(a.FamiliarTextGranted,Is.EqualTo(e.FamiliarTextGranted));}}
  [Test,Timeout(210000)]public void P1TemplateFilesInitializeCompleteState(){string a=CopyBundle("A");var flow=Doc<FlowContentDocument>(a,"flow");var training=Binding("training-choice");training.IsChoice=true;training.Condition="training-here";flow.Anchors.Single(x=>x.Id=="noon").Entries=new[]{training};Save(a,"flow",flow);string b=CopyBundle("B",a);var t=Doc<TemplatesDocument>(b,"templates");var init=t.Initializations.Single(x=>x.Id==t.Templates.Single(y=>y.Id==t.DefaultId).InitializationId);init.Balance.Value++;init.Body.Regions.Single(x=>x.RegionId=="chest_upper").StrengthMicro.Value+=1000000;Save(b,"templates",t);var pa=Load(a);var pb=Load(b);Different(pa,pb);long[] balances=new long[2],difficulty=new long[2];int index=0;foreach(var package in new[]{pa,pb})using(var r=new Run(this,index==0?"runA":"runB",package)){r.NewGame();AssertInitial(r,package);balances[index]=r.Read<LifeActorState>("life").Wallet.Balance;r.Until(v=>v.Actions.Any(x=>x.Enabled&&x.Id=="begin-set"));var begin=r.Session.ReadView().Actions.Single(x=>x.Enabled&&x.Id=="begin-set"&&x.StringValue=="manual"&&x.IntValue==0);r.Send(begin);var request=r.Read<TrainingDayState>("training").Workout.PendingRequest;Assert.That(request.ExerciseId,Is.EqualTo("bench_press"));Assert.That(request.Tier,Is.EqualTo(1));Assert.That(r.Session.ReadView().TrainingInput,Is.Not.Null);difficulty[index]=request.DifficultyMicro;File.WriteAllText(Path.Combine(r.Dir,"actual-first-set.json"),JsonUtility.ToJson(request,true));index++;}Assert.That(balances[1]-balances[0],Is.EqualTo(1));Assert.That(difficulty[1],Is.LessThan(difficulty[0]),"Configured S is consumed by actual first-set difficulty");}
  internal static EventBinding Binding(string id)=>new EventBinding{EventId=id,Condition="",Enabled=true,Weight=1,MaximumStarts=-1,CooldownDays=0,ExclusiveGroup="",Consume=Array.Empty<AnchorConsumption>()};
  internal static void DefaultAt(string dir,string anchor,string eventId){var f=Doc<FlowContentDocument>(dir,"flow");var a=f.Anchors.Single(x=>x.Id==anchor);a.Entries=Array.Empty<EventBinding>();a.Defaults=new[]{Binding(eventId)};Save(dir,"flow",f);}
  [Test,Timeout(210000)]public void P1WorkDefaultAndLegalAnchorConsumeFiles(){string a=CopyBundle("A");DefaultAt(a,"morning","ordinary-work");string b=CopyBundle("B",a);DefaultAt(b,"morning","ordinary-calm");var f=Doc<FlowContentDocument>(b,"flow");foreach(var anchor in f.Anchors.Where(x=>x.Order>=2))anchor.Order++;f.Anchors=f.Anchors.Concat(new[]{new AnchorDefinition{Id="p1-extra",Name="配置验收时段",Kind="ordinary",MealSlot="",UnlockCondition="",Order=2,StandardSeconds=0,TrainingAllowed=true,EditableTraining=true,PlanEditing=false,Entries=Array.Empty<EventBinding>(),Defaults=new[]{Binding("ordinary-calm")}}}).ToArray();Save(b,"flow",f);var pa=Load(a);var pb=Load(b);Different(pa,pb);foreach(var p in new[]{pa,pb})using(var r=new Run(this,p==pa?"runA":"runB",p)){r.NewGame();using(ContentRuntime.Push(p)){Assert.That(SessionContent.Anchors(r.Read<SessionState>("session")).Contains("p1-extra"),Is.EqualTo(p==pb));}string handler=p==pa?"work/":"calm/";r.Until(v=>v.ScreenId.StartsWith(handler)&&r.Read<FlowState>("flow").AnchorId=="morning"&&v.Actions.Any(x=>x.Enabled&&x.Id=="continue"));if(p==pb)Assert.That(r.CompletedTitles,Does.Contain("配置验收时段"),"New anchor must actually be entered and completed");long before=r.Read<LifeActorState>("life").Wallet.Balance;int w=r.Read<LifeActorState>("life").Wallet.Affluence;r.Send(r.Session.ReadView().Actions.First(x=>x.Enabled&&x.Id=="continue"),true);Assert.That(r.Read<LifeActorState>("life").Wallet.Balance-before,Is.EqualTo(p==pa?50L+w:0L));r.Reopen(p,p);}}
  internal static EventCallPayload Call(long amount=0)=>new EventCallPayload{StoryId="",ShopId="",IncomeId="",TimeMode="none",Seconds=0,Effects=amount==0?Array.Empty<ConfiguredEffect>():new[]{new ConfiguredEffect{Kind="money",Target="self",Id="p1-return",Amount=amount}}};
  internal static void StoryBundle(string dir,long amount){var f=Doc<FlowContentDocument>(dir,"flow");var call=Call();call.StoryId="branch_example";f.Events=f.Events.Concat(new[]{new ConfiguredEvent{Id="p1-story",Title="配置分支",Root="story",Nodes=new[]{new ConfiguredNode{Id="story",Handler="narrative",Title="",Next="",Branches=new[]{new FlowEdge{ConditionKey="result:listened",TargetNodeId="heard-effect"},new FlowEdge{ConditionKey="result:asked",TargetNodeId="asked-effect"}},Call=call},new ConfiguredNode{Id="heard-effect",Handler="effects",Title="",Next="",Branches=Array.Empty<FlowEdge>(),Call=Call(amount)},new ConfiguredNode{Id="asked-effect",Handler="effects",Title="",Next="",Branches=Array.Empty<FlowEdge>(),Call=Call(amount+1)}}}}).ToArray();Save(dir,"flow",f);DefaultAt(dir,"morning","p1-story");}
  [Test,Timeout(210000)]public void P1StoryReturnCommitsOnceAndRestartsOrdinaryEvent(){string a=CopyBundle("A");StoryBundle(a,5);string b=CopyBundle("B",a);var f=Doc<FlowContentDocument>(b,"flow");foreach(var node in f.Events.Single(x=>x.Id=="p1-story").Nodes.Where(n=>n.Handler=="effects"))node.Call.Effects.Single().Amount+=2;Save(b,"flow",f);var pa=Load(a);var pb=Load(b);Different(pa,pb);foreach(string choice in new[]{"listen","ask"})foreach(var p in new[]{pa,pb})using(var r=new Run(this,(p==pa?"A-":"B-")+choice,p)){r.NewGame();r.Until(v=>v.ScreenId=="narrative"&&v.Actions.Any(x=>x.Id=="story-choice"&&x.Enabled));long before=r.Read<LifeActorState>("life").Wallet.Balance;r.Send(r.Session.ReadView().Actions.Single(x=>x.Id=="story-choice"&&x.StringValue==choice));r.Reopen(p,p,false);Assert.That(r.Session.ReadView().Actions.Any(x=>x.Id=="story-choice"&&x.StringValue==choice&&x.Enabled),Is.True,"Ordinary unfinished event restarts at its origin");Assert.That(r.Read<LifeActorState>("life").Wallet.Balance,Is.EqualTo(before));r.Send(r.Session.ReadView().Actions.Single(x=>x.Id=="story-choice"&&x.StringValue==choice));r.Send(r.Session.ReadView().Actions.Single(x=>x.Id=="story-continue"&&x.Enabled),true);var story=r.Read<NarrativeState>("narrative");Assert.That(story.Completed,Is.True);Assert.That(story.Result,Is.EqualTo(choice=="listen"?"listened":"asked"));Assert.That(r.Read<LifeActorState>("life").Wallet.Balance-before,Is.EqualTo((p==pa?5:7)+(choice=="ask"?1:0)));Assert.That(FlowEngine.Current(r.Read<FlowState>("flow"))?.Phase,Is.Not.EqualTo(NodePhase.Started),"No extra player return confirmation");r.Reopen(p,p);}}
  [Test,Timeout(210000)]public void P1InvalidReferenceAndWholeRunContentSnapshot(){string a=CopyBundle("A");DefaultAt(a,"morning","ordinary-calm");string b=CopyBundle("B",a);DefaultAt(b,"morning","ordinary-work");var deep=Doc<FlowContentDocument>(b,"flow");var condition=new ConditionDefinition{Op="True",Key="",Value="",Children=Array.Empty<ConditionDefinition>()};for(int level=0;level<12;level++)condition=new ConditionDefinition{Op="All",Key="",Value="",Children=new[]{condition}};deep.Conditions=deep.Conditions.Concat(new[]{new NamedCondition{Id="p1-deep",Rule=condition}}).ToArray();Save(b,"flow",deep);Assert.That(ContentJson.Serialize(Doc<FlowContentDocument>(b,"flow")),Is.EqualTo(ContentJson.Serialize(deep)));using(ContentRuntime.Push(ContentPackage.FromDirectory(b)))Assert.That(FlowContent.Evaluate("p1-deep",key=>throw new InvalidOperationException("Unexpected fact")),Is.True);var pa=Load(a);var pb=Load(b);Different(pa,pb);using(var r=new Run(this,"run",pa)){r.NewGame();string before=JsonUtility.ToJson(r.Session.InspectSnapshot());string invalid=CopyBundle("invalid",b);var f=Doc<FlowContentDocument>(invalid,"flow");f.Events.Single(x=>x.Id=="ordinary-calm").Nodes.Single().Handler="narrative";f.Events.Single(x=>x.Id=="ordinary-calm").Nodes.Single().Call.StoryId="p1-missing-story";Save(invalid,"flow",f);var ex=Assert.Catch(()=>GameSession.ValidateContentPackage(ContentPackage.FromDirectory(invalid)));Assert.That(ex.Message,Does.Contain("flow").And.Contain("StoryId"));File.WriteAllText(Path.Combine(output,"invalid-diagnostic.txt"),ex.ToString());Assert.That(JsonUtility.ToJson(r.Session.InspectSnapshot()),Is.EqualTo(before));r.Reopen(pb,pa);r.Until(v=>v.ScreenId.StartsWith("calm/")&&r.Read<FlowState>("flow").AnchorId=="morning");r.Send(r.Session.ReadView().Actions.First(x=>x.Id=="open-menu"&&x.Enabled));r.NewGame();r.Identity(pb);r.Until(v=>v.ScreenId.StartsWith("work/")&&r.Read<FlowState>("flow").AnchorId=="morning");}}
 }
}
